<script setup lang="ts">
import {onMounted,ref} from 'vue';import {ElAlert,ElButton,ElInput,ElEmpty,ElMessageBox} from 'element-plus';import {requestClient} from '#/api/request';
type Conversation={id:string;title:string;canSend:boolean;enabled:number};type Message={id:string;mine:boolean;content:string;create_time:string};
const rows=ref<Conversation[]>([]),current=ref<Conversation>(),messages=ref<Message[]>([]),text=ref(''),busy=ref(false),error=ref(''),more=ref(false);
async function load(){busy.value=true;error.value='';try{rows.value=await requestClient.get('/growth/conversations');if(current.value){current.value=rows.value.find(r=>r.id===current.value?.id);if(current.value)await read()}}catch{error.value='交流加载失败，请重试'}finally{busy.value=false}}
async function read(append=false){if(!current.value)return;const result=await requestClient.get<Message[]>('/growth/bookings/'+current.value.id+'/messages',{params:append?{before:messages.value.at(-1)?.id}:{}});messages.value=append?[...messages.value,...result]:result;more.value=result.length===50}
async function choose(row:Conversation){if(busy.value)return;current.value=row;text.value='';messages.value=[];busy.value=true;try{await read()}catch{error.value='消息读取失败，请刷新'}finally{busy.value=false}}
async function send(){if(!current.value?.canSend||busy.value||!text.value.trim())return;busy.value=true;try{await requestClient.post('/growth/bookings/'+current.value.id+'/messages',{content:text.value.trim()});text.value='';await read()}catch{}finally{busy.value=false}}
async function remove(m:Message){try{await ElMessageBox.confirm('撤回后双方无法读取这条消息。','撤回消息');busy.value=true;await requestClient.delete('/growth/bookings/'+current.value?.id+'/messages/'+m.id);await read()}catch{}finally{busy.value=false}}
async function earlier(){busy.value=true;try{await read(true)}catch{error.value='读取失败，请重试'}finally{busy.value=false}}
onMounted(load);
</script>
<template><ElAlert title="仅预约双方可以访问。学生单独开启交流授权后才能发送消息；此处不提供紧急响应。" :closable="false"/><ElAlert v-if="error" :title="error" type="error" :closable="false"/><div class="inbox"><aside><ElButton :loading="busy" @click="load">刷新预约</ElButton><button v-for="r in rows" :key="r.id" :class="{active:current?.id===r.id}" :disabled="busy" @click="choose(r)"><strong>{{r.title}}</strong><span>{{r.canSend?'可以交流':'当前只读'}}</span></button><ElEmpty v-if="!rows.length&&!busy" description="暂无本人参与的预约"/></aside><main v-if="current"><h3>{{current.title}}</h3><div v-for="m in messages" :key="m.id" class="message" :class="{mine:m.mine}"><header><strong>{{m.mine?'我':'预约对方'}}</strong><ElButton v-if="m.mine" link :disabled="busy" @click="remove(m)">撤回</ElButton></header><p>{{m.content}}</p><small>{{String(m.create_time).replace('T',' ').slice(0,16)}}</small></div><ElButton v-if="more" :disabled="busy" @click="earlier">更早消息</ElButton><ElEmpty v-if="!messages.length" description="暂无消息"/><ElInput v-model="text" type="textarea" :rows="4" maxlength="1000" show-word-limit :disabled="!current.canSend||busy" placeholder="填写预约交流内容" aria-label="预约交流内容"/><ElButton type="primary" :disabled="!current.canSend||busy||!text.trim()" style="margin-top:16px" @click="send">发送消息</ElButton></main><ElEmpty v-else description="选择一条预约查看交流"/></div><p>本系统不能替代专业心理咨询</p></template>
<style scoped>.inbox{display:grid;grid-template-columns:230px minmax(0,1fr);gap:24px;margin-top:24px}aside>button:not(.el-button){width:100%;display:flex;flex-direction:column;gap:8px;padding:16px;text-align:left;border:1px solid var(--el-border-color);border-radius:12px;margin-top:12px;background:var(--el-bg-color);cursor:pointer}aside>button.active{border-color:var(--el-color-primary);background:var(--el-color-primary-light-9)}span,small{font-size:12px;color:var(--el-text-color-regular)}.message{padding:16px;border:1px solid var(--el-border-color);border-radius:12px;margin:16px 0}.mine{background:var(--el-color-primary-light-9)}header{display:flex;justify-content:space-between;align-items:center}p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}@media(max-width:650px){.inbox{grid-template-columns:1fr}}</style>
